tasks.solution:
terraform {
  required_providers { local = { source = "hashicorp/local", version = "~> 2.5" } }
}
variable "project" { type = string, default = "devops-academy" }
resource "local_file" "example" {
  filename = "${path.module}/out/${var.project}.txt"
  content  = "infra managed by terraform"
}
output "file_path" { value = local_file.example.filename }
terraform init && terraform validate && terraform plan && terraform apply

terraform {
  backend "s3" {
    bucket         = "org-tfstate-lab"
    key            = "lab/terraform.tfstate"
    region         = "eu-central-1"
    dynamodb_table = "tf-locks"
    encrypt        = true
  }
}
# затем: terraform init -migrate-state

mkdir -p modules/service envs/staging
cat > modules/service/variables.tf <<'EOF'
variable "name" { type = string }
variable "environment" {
  type = string
  validation {
    condition     = contains(["staging", "prod"], var.environment)
    error_message = "environment должен быть staging или prod"
  }
}
EOF
terraform fmt -recursive
terraform validate
